<script>document.querySelectorAll('input[type=password]').forEach((input,index)=>{if(!input.id)input.id='account-password-'+index;const wrap=document.createElement('div');wrap.className='password-field';input.before(wrap);wrap.append(input);const button=document.createElement('button');button.type='button';button.className='password-toggle';button.textContent='Show';button.setAttribute('aria-label','Show password');button.setAttribute('aria-controls',input.id);button.setAttribute('aria-pressed','false');button.onclick=()=>{const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-label',show?'Hide password':'Show password');button.setAttribute('aria-pressed',String(show));};wrap.append(button);});document.querySelectorAll('label').forEach(label=>{if(label.htmlFor||label.querySelector('input,select'))return;const next=label.nextElementSibling;const input=next?.matches('input,select')?next:next?.querySelector('input');if(input){if(!input.id)input.id='field-'+Math.random().toString(36).slice(2);label.htmlFor=input.id;}});</script>@stack('scripts')</body></html>
